import{partnerInfo}from'./partners.js';
import * as T from'./vendor/three.module.min.js';import{evolutionFrame,EVOLUTION_DURATION,ease}from'./evolution-timeline.js';import{FORM_HEIGHTS}from'./world-layout.js';
function glowTexture(){const n=64,data=new Uint8Array(n*n*4);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const r=Math.hypot((x+.5)/n*2-1,(y+.5)/n*2-1),i=(y*n+x)*4;data[i]=255;data[i+1]=247;data[i+2]=218;data[i+3]=Math.round(Math.max(0,1-r)**2.4*255);}const tex=new T.DataTexture(data,n,n);tex.needsUpdate=true;return tex;}
export class EvolutionStage{
 constructor(world,from,to,oldForm,newForm,{onFrame=()=>{},reduced=false}={}){
  this.palette=partnerInfo(world.partner);this.world=world;this.from=from;this.to=to;this.oldForm=oldForm;this.newForm=newForm;this.onFrame=onFrame;this.reduced=reduced;this.time=0;this.resolved=false;this.root=new T.Group();this.root.position.set(world.nav.player.x,world.nav.y||0,world.nav.player.z);this.root.rotation.y=world.creature.rotation.y+(world.locomotion?.forwardYaw||0);world.scene.add(this.root);this.height=Math.max(FORM_HEIGHTS[from],FORM_HEIGHTS[to]);this.size=Math.max(.8,this.height*.72);this.texture=glowTexture();this.saved={land:world.land.visible,effects:world.effects.visible,creature:world.creature.visible,rival:world.rival.visible,background:world.scene.background.clone(),fog:world.scene.fog,exposure:world.renderer.toneMappingExposure};world.land.visible=false;world.effects.visible=false;world.creature.visible=false;world.rival.visible=false;world.scene.background.set('#10212e');world.scene.fog=null;
  this.oldRoot=new T.Group();this.newRoot=new T.Group();this.oldRoot.add(oldForm.model);this.newRoot.add(newForm.model);this.oldRoot.rotation.y=-oldForm.forwardYaw;this.newRoot.rotation.y=-newForm.forwardYaw;this.root.add(this.oldRoot,this.newRoot);this.originalMaterials=new Map();for(const f of[oldForm,newForm])f.model.traverse(o=>{if(o.isMesh){this.originalMaterials.set(o,o.material);o.castShadow=false;o.receiveShadow=false;}});this.silhouette=new T.MeshBasicMaterial({color:'#fff4cf',toneMapped:false});
  const add=(geometry,material)=>{const o=new T.Mesh(geometry,material);this.root.add(o);return o;};const additive=colour=>new T.MeshBasicMaterial({color:colour,transparent:true,opacity:0,blending:T.AdditiveBlending,depthWrite:false,side:T.DoubleSide,toneMapped:false});
  this.floor=add(new T.CircleGeometry(this.size*5,64),new T.MeshBasicMaterial({color:'#152d38',side:T.DoubleSide}));this.floor.rotation.x=-Math.PI/2;this.floor.position.y=-.025;
  this.rings=[];for(let i=0;i<3;i++){const ring=add(new T.TorusGeometry(this.size*(.85+i*.23),.012+i*.005,5,96),additive(i===1?'#fae4a5':this.palette.accent));ring.rotation.x=Math.PI/2;ring.position.y=.015+i*.014;this.rings.push(ring);}
  this.ribbons=[];for(let i=0;i<4;i++){const geo=new T.BufferGeometry(),a=new Float32Array(65*2*3),indices=[];for(let j=0;j<64;j++){let k=j*2;indices.push(k,k+1,k+2,k+1,k+3,k+2);}geo.setAttribute('position',new T.BufferAttribute(a,3));geo.setIndex(indices);this.ribbons.push(add(geo,additive(i%2?this.palette.accent:'#ffe3a1')));}
  this.sparks=new T.Points(new T.BufferGeometry(),new T.PointsMaterial({map:this.texture,color:'#fff1bf',size:this.size*.105,transparent:true,opacity:0,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));this.sparks.geometry.setAttribute('position',new T.BufferAttribute(new Float32Array(144*3),3));this.root.add(this.sparks);
  this.glows=[];for(let i=0;i<3;i++){const sprite=new T.Sprite(new T.SpriteMaterial({map:this.texture,color:i===1?this.palette.accent:'#fff1bd',transparent:true,opacity:0,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));this.root.add(sprite);this.glows.push(sprite);}
  this.light=new T.PointLight('#fff0bd',0,this.height*9,1.5);this.light.position.y=this.height*.7;this.root.add(this.light);this.promise=new Promise(resolve=>this.resolve=resolve);this.update(0);
 }
 update(dt){this.time=Math.min(EVOLUTION_DURATION,this.time+dt);const w=this.world,f=evolutionFrame(this.time,this.from,this.to,{reduced:this.reduced,aspect:w.camera.aspect}),h=this.height,s=this.size;this.frame=f;w.land.visible=this.time<.85&&this.saved.land;w.scene.background.copy(this.saved.background).lerp(new T.Color('#10212e'),ease(this.time/1.1));
  this.oldRoot.visible=f.oldVisible;this.newRoot.visible=f.newVisible;for(const root of[this.oldRoot,this.newRoot]){root.position.y=f.lift;root.scale.set(f.scale*(1+f.landing*.025),f.scale*(1-f.landing*.035),f.scale*(1+f.landing*.025));}this.oldRoot.rotation.x=f.lift>.08?-.08*f.charge:0;this.newRoot.rotation.x=f.landing*.025;const silhouette=f.glow>.4;for(const[o,material]of this.originalMaterials)o.material=silhouette?this.silhouette:material;
  this.silhouette.color.setRGB(1,.92+.08*f.glow,.72+.28*f.glow);this.light.intensity=f.charge*(f.major?7:5);this.rings.forEach((ring,i)=>{ring.material.opacity=f.ring*(.7-i*.14);ring.rotation.z=this.time*(i%2?-.25:.2);ring.scale.setScalar(1+f.landing*.6+i*f.landing*.12);});
  this.ribbons.forEach((mesh,i)=>{const a=mesh.geometry.attributes.position;for(let j=0;j<=64;j++){const u=j/64,angle=u*Math.PI*3.4-this.time*(f.major?2.2:1.7)+i*Math.PI/2,r=s*(.5+.42*Math.sin(u*Math.PI))*(1+f.reveal*.8),y=u*(h+1)+f.lift;const width=(.018+.06*Math.sin(u*Math.PI))*s;for(let k=0;k<2;k++)a.setXYZ(j*2+k,Math.cos(angle)*(r+(k?width:-width)),y,Math.sin(angle)*(r+(k?width:-width)));}a.needsUpdate=true;mesh.geometry.computeBoundingSphere();mesh.material.opacity=this.reduced?f.ribbons*.12:f.ribbons*(i>2&&!f.major?.35:.7);});
  const a=this.sparks.geometry.attributes.position;for(let i=0;i<a.count;i++){const u=((i*.61803398875+this.time*.1)%1),angle=i*2.39996+this.time*.35,r=s*(.65+(i%7)/7)*(1+f.reveal*.7);a.setXYZ(i,Math.cos(angle)*r,u*(h+1.2)+f.lift*.3,Math.sin(angle)*r);}a.needsUpdate=true;this.sparks.geometry.computeBoundingSphere();this.sparks.material.opacity=f.particles*.8;
  this.glows.forEach((g,i)=>{g.position.y=h*(i===0?.6:i===1?.35:.78)+f.lift;const radius=i===0?s*(.4+f.glow*6):s*(1.2+f.glow*3);g.scale.setScalar(radius);g.material.opacity=i===0?Math.min(.8,.15*f.charge+f.glow*.65):f.glow*.5;});
  const eye=new T.Vector3(f.camera.x,f.camera.y,f.camera.z).applyAxisAngle(new T.Vector3(0,1,0),this.root.rotation.y).add(this.root.position),target=this.root.position.clone();target.y+=f.targetY;if(w.camera.aspect>1.45){const a=f.yaw+this.root.rotation.y;target.add(new T.Vector3(Math.cos(a),0,-Math.sin(a)).multiplyScalar(this.height*.7*f.reveal));}w.camera.position.lerp(eye,1-Math.exp(-Math.max(.016,dt)*8));w.target.copy(target);w.camera.lookAt(target);w.camera.fov=f.fov;w.camera.updateProjectionMatrix();this.onFrame(f);
  if(f.done&&!this.resolved){this.resolved=true;this.resolve({skipped:!!this.skipped});}return f;
 }
 skip(){this.skipped=true;this.time=EVOLUTION_DURATION;this.update(0);}
 dispose({keepNew=false}={}){const w=this.world;for(const[o,material]of this.originalMaterials)o.material=material;this.root.remove(this.oldRoot,this.newRoot);this.oldRoot.remove(this.oldForm.model);this.newRoot.remove(this.newForm.model);w.disposeModel(this.oldForm.model);if(!keepNew)w.disposeModel(this.newForm.model);this.root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});this.texture.dispose();this.silhouette.dispose();w.scene.remove(this.root);w.land.visible=this.saved.land;w.effects.visible=this.saved.effects;w.creature.visible=this.saved.creature;w.rival.visible=this.saved.rival;w.scene.background.copy(this.saved.background);w.scene.fog=this.saved.fog;w.renderer.toneMappingExposure=this.saved.exposure;if(!this.resolved){this.resolved=true;this.resolve({cancelled:true});}}
}
